source("/private/tmp/claude-501/-Users-pbtz-src-github-com-pedrobtz-zuspark/23786a96-505c-4b1e-b66f-e320fa1ada7b/scratchpad/hunt/hunt-2/harness.R")
all4 <- list(B(1), B(2), B(3), B(4)); T <- transport_cnd()
M <- function(name) list(metrics = list(metrics = list(list(name = name, plan_id = 1, parent = 0))))
OM <- function(name) list(observed_metrics = list(list(name = name, plan_id = 1)))
cat("## two metrics, observed metrics across a reattach, unknown types\n")
srv <- new_server(list(c(list(OM("a")), all4, list(M("first"), list(checkpoint_command_result = list()), list(extension = list(type_url = "x/y", value = as.raw(1))), T)), list(OM("b"), OM("a"), M("second"), list(), RC())))
con <- srv$connect(); q <- new_q(con); d <- try_show(spark_collect(q))
cat("   nrow", nrow(d), "metrics:", q$metrics$metrics[[1]]$name, "| observed:", vapply(q$observed_metrics, function(m) m$name, ""), "| skipped", q$skipped, "| reatt", q$reattaches, "\n")
cat("## observed metrics on the same response as a batch and on RC\n")
srv <- new_server(list(list(c(B(1), OM("with-batch")), c(RC(), OM("with-rc")))))
con <- srv$connect(); q <- new_q(con); d <- try_show(spark_collect(q)); cat("   observed:", vapply(q$observed_metrics, function(m) m$name, ""), "\n")
cat("## state of a query after a failed re-run (stale rows/metrics?)\n")
srv <- new_server(list(c(all4, list(M("m1"), RC())), list(B(1), spark_cnd("X"))))
con <- srv$connect(); q <- new_q(con); d <- spark_collect(q); op1 <- q$operation_id; e <- try_show(spark_collect(q))
cat("   after failure: rows", q$rows, "metrics", q$metrics$metrics[[1]]$name, "op changed:", !identical(op1, q$operation_id), "\n"); print(q)
cat("## same query object run twice gives two operations\n")
srv <- new_server(list(c(all4, list(RC())), c(all4, list(RC())))); con <- srv$connect(); q <- new_q(con); a <- spark_collect(q); b <- spark_collect(q)
ops <- vapply(Filter(function(l) l$method == "ExecutePlan", srv$log), function(l) l$req$operation_id, ""); cat("   identical data:", identical(a, b), "distinct ops:", length(unique(ops)) == 2, "\n")

cat("\n#### session id handling\n")
cat("## first answers without server_side_session_id; learnt later; echoed after\n")
k <- 0
srv <- new_server(list(), list(Config = function(req, srv) { k <<- k + 1; if (k <= 2) list(server_side_session_id = "") else list() }))
con <- srv$connect(); print(spark_session_id(con)[["server"]])
spark_config(con, "a"); spark_config(con, "a"); spark_config(con, "a")
for (l in srv$log) cat("   sent observed id:", l$req$client_observed_server_side_session_id %||% "<none>", "\n")
cat("## response session_id empty / absent accepted?\n")
srv <- new_server(list(), list(Config = function(req, srv) list(session_id = ""))); con <- try_show(srv$connect()); print(class(con))
cat("## connect: Config answers for another session\n")
srv <- new_server(list(), list(Config = function(req, srv) list(session_id = "nope"))); con <- try_show(srv$connect()); srv$show()
cat("## connect: AnalyzePlan answers with other server-side id (release sent?)\n")
srv <- new_server(list(), list(AnalyzePlan = function(req, srv) list(server_side_session_id = "other", spark_version = list(version = "4.2.1")))); con <- try_show(srv$connect()); srv$show()
for (v in c("3.4.9", "3.5.0", "3.5.0-SNAPSHOT", "", "4", "abc", "10.0.0", "3.10.1")) { srv <- new_server(list(), list(AnalyzePlan = function(req, srv) list(spark_version = list(version = v)))); cat("## version", dQuote(v), ":"); con <- try_show(srv$connect()); cat(" ", class(con)[1], "| calls:", paste(srv$methods(), collapse = " "), "\n") }

cat("\n#### error details\n")
E <- function(type, cause = NULL, cls = NULL) { e <- list(error_type_hierarchy = c(type, "java.lang.Throwable"), message = paste("msg", type), stack_trace = list(list(declaring_class = "C", method_name = "m", file_name = "f.scala", line_number = 7), list(declaring_class = "D", method_name = "n", line_number = -2)))
  if (!is.null(cause)) e$cause_idx <- cause; if (!is.null(cls)) e$spark_throwable <- list(error_class = cls, sql_state = "42000", message_parameters = c(a = "1", b = "2"), query_contexts = list(list(object_type = "", object_name = "", start_index = 3, stop_index = 9, fragment = "1/0"))); e }
det <- function(title, resp) { cat("##", title, "\n"); srv <- new_server(list(), list(FetchErrorDetails = function(req, srv) resp)); con <- srv$connect()
  err <- zuspark:::as_zuspark_error(spark_cnd(), con); r <- try_show(spark_error_details(err))
  if (!inherits(r, "condition")) for (x in r) cat("   -", x$type[1], "| cause ->", x$cause, "| class", x$error_class, "| params", paste(names(x$message_parameters), x$message_parameters, collapse = ","), "| stack", nrow(x$stack), paste(x$stack$file, collapse = "/"), "| ctx", nrow(x$contexts), "\n")
  invisible(r) }
det("root 0, chain 0->1->2", list(root_error_idx = 0, errors = list(E("A", 1, "CLS"), E("B", 2), E("C"))))
det("root 2, chain 2->0->1 (cause must point at the right element)", list(root_error_idx = 2, errors = list(E("B", 1), E("C"), E("A", 0))))
det("root 1, chain 1->2->0", list(root_error_idx = 1, errors = list(E("C"), E("A", 2), E("B", 0))))
det("root idx absent", list(errors = list(E("A", 1), E("B"))))
det("root idx out of range", list(root_error_idx = 5, errors = list(E("A", 1), E("B"))))
det("cause idx out of range", list(root_error_idx = 0, errors = list(E("A", 9), E("B"))))
det("self cause", list(root_error_idx = 0, errors = list(E("A", 0))))
det("no errors", list())
det("error without anything", list(root_error_idx = 0, errors = list(list())))
